// Tiny jest-compatible runner: supports describe/it/expect(toBe) and exits 1 on failure.
// Deliberately minimal — it exists so the demo verifies with zero installs.

let currentTests = null;

function describe(name, fn) {
  fn();
}

function it(name, fn) {
  if (currentTests) currentTests.push({ name, fn });
}

function expect(actual) {
  return {
    toBe(expected) {
      if (actual !== expected) {
        throw new Error(
          'expected ' + JSON.stringify(actual) + ' to be ' + JSON.stringify(expected)
        );
      }
    },
  };
}

global.describe = describe;
global.it = it;
global.expect = expect;

async function run() {
  const fs = require('fs');
  const path = require('path');
  const testDir = path.join(process.cwd(), 'tests');
  const files = fs.existsSync(testDir)
    ? fs.readdirSync(testDir).filter((f) => f.endsWith('.test.js'))
    : [];

  let failures = 0;
  for (const file of files) {
    currentTests = [];
    require(path.join(testDir, file));
    const tests = currentTests;
    currentTests = null;

    console.log(file);
    for (const t of tests) {
      try {
        await t.fn();
        console.log('  \u2713 ' + t.name);
      } catch (err) {
        failures++;
        console.error('  \u2715 ' + t.name);
        console.error(String((err && err.stack) || err));
      }
    }
  }

  if (failures > 0) {
    console.error(failures + ' test(s) failed');
    process.exit(1);
  }
  console.log('all tests passed');
}

module.exports = { run };
